def anchors(p,tokens):
    lines=p.read_bytes().decode('utf-8-sig').splitlines();out=[]
    for token in tokens:
        hits=[dict(line=i+1,text=ln,context='\n'.join(lines[max(0,i-2):i+3])) for i,ln in enumerate(lines) if token in ln]
        out.append(dict(token=token,hits=hits,status='FOUND' if hits else 'OPTIONAL_ANCHOR_ABSENT_SKIP'))
    return dict(file=row(p),anchors=out)
